mapper.select:
SELECT 
FROM tb_menu m LEFT JOIN tb_menu p ON p.menu_id = m.parent_menu_id
WHERE m.menu_id = #{menuId}

SELECT action_cd FROM tb_permission WHERE menu_id = #{menuId}
ORDER BY CASE action_cd WHEN 'READ' THEN 1 WHEN 'CREATE' THEN 2 WHEN 'UPDATE' THEN 3
                        WHEN 'DELETE' THEN 4 WHEN 'EXCEL' THEN 5 ELSE 6 END

mapper.delete:
DELETE FROM tb_role_permission rp
USING tb_permission p
WHERE rp.perm_id = p.perm_id AND p.menu_id = #{menuId}

mapper.sql:
WITH RECURSIVE subtree AS (
    SELECT menu_id, depth FROM tb_menu WHERE menu_id = #{menuId}
    UNION ALL
    SELECT c.menu_id, c.depth FROM tb_menu c JOIN subtree s ON c.parent_menu_id = s.menu_id
)
